package me.never.blockparty;
import org.bukkit.*;import org.bukkit.generator.ChunkGenerator;import org.bukkit.generator.WorldInfo;import org.bukkit.plugin.java.JavaPlugin;
public final class NeverBlockParty extends JavaPlugin{
 public void onEnable(){saveDefaultConfig();String n=getConfig().getString("world","blockparty");World w=Bukkit.getWorld(n);if(w==null){WorldCreator c=new WorldCreator(n);c.generator(new VoidGenerator());w=c.createWorld();}if(w==null){getLogger().severe("Could not create Block Party world.");getServer().getPluginManager().disablePlugin(this);return;}w.setGameRule(GameRule.DO_DAYLIGHT_CYCLE,false);w.setGameRule(GameRule.DO_WEATHER_CYCLE,false);w.setTime(6000);w.setStorm(false);w.setThundering(false);Arena a=new Arena(this,w);a.build();Game g=new Game(this,a);getServer().getPluginManager().registerEvents(g,this);getCommand("blockparty").setExecutor(new BPCommand(g));}
 static final class VoidGenerator extends ChunkGenerator{public void generateNoise(WorldInfo i,java.util.Random r,int x,int z,ChunkData d){}public boolean shouldGenerateNoise(){return false;}public boolean shouldGenerateSurface(){return false;}public boolean shouldGenerateBedrock(){return false;}public boolean shouldGenerateCaves(){return false;}public boolean shouldGenerateDecorations(){return false;}public boolean shouldGenerateMobs(){return false;}public boolean shouldGenerateStructures(){return false;}}
}